package com.bank.lookup;

import java.util.*;
import java.util.function.Supplier;
import java.util.logging.*;

public class SupplierDemo {
    private static final Logger log = Logger.getLogger("Lookup");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        EmployeeLookupService service = new EmployeeLookupService();

        Employee found = service.findOrDefault("Rajesh");
        Employee missing = service.findOrDefault("Nobody");
        log.info(() -> "found   = " + found.getName());
        log.info(() -> "missing = " + missing.getName());
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final double salary;
    Employee(String name, double salary) { this.name = name; this.salary = salary; }
    String getName() { return name; }
    double getSalary() { return salary; }
}

// ─── Would be in service/EmployeeLookupService.java ───
class EmployeeLookupService {
    // the default is produced LAZILY via a Supplier
    private final Supplier<Employee> defaultEmployee = () -> new Employee("UNKNOWN", 0);

    private final Map<String, Employee> db = Map.of(
        "Rajesh", new Employee("Rajesh", 1000000));

    Employee findOrDefault(String name) {
        return Optional.ofNullable(db.get(name))
            .orElseGet(defaultEmployee);   // build default ONLY if empty
    }
}
